INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('a933caaac21cd461', 'act_952386692927446', 'ae179d34b851e3e1', 1, 1, 1, 'live', 'Day one of not taking this necklace off', 'Wear one piece into the shower, the gym and to bed for a week and show it under the same light at the end.', 'Anyone who has had a cheap necklace turn on them. This one travels to every audience.', 'Twisted Herringbone, Gold Link Earrings, any chain', 'Day counter', NULL, '["Day one of not taking this necklace off.", "I''m about to do the thing you''re not supposed to do with gold jewelry.", "It''s been a week in the shower with this. Look."]', '[{"label": "Open · 0 to 3s", "text": "Water hitting the piece, the shelf shot."}, {"label": "Middle", "text": "Gym and sleep with the counter climbing."}, {"label": "Close", "text": "The piece on a white towel in daylight. Say the colour has not moved."}]', 'Day 7. Shower, gym, sleep. / Tarnish free. Sweat proof.', 'Same piece, same spot, day 1 and day 7. Say gold-filled or gold PVD.', 'Say waterproof. Say sweat proof and tarnish free. No vinegar or magnet tests.', NULL, 'Water running over the necklace on your neck under the shower head, phone propped on the shelf. No face needed yet.', 'Cut to the gym mirror, then the pillow, with a day counter on screen: Day 1, Day 4, Day 7.', 'The top creator videos in jewelry right now are all this: one person, one piece, a list of abuses, a reveal. It is also the shape that converts for us.', '[{"brand": "Oak & Luna", "what": "\"I work out in this, I shower in this, I jump in the ocean in this.\" The abuse list.", "url": "https://app.tryatria.com/ad/m1417233863835377"}, {"brand": "JAXXON", "what": "\"Three months later, no fading, no green neck.\" The time stamp as the payoff.", "url": "https://app.tryatria.com/ad/m1362619162625683"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '810e9ea87da74104', 'act_952386692927446', 'a933caaac21cd461', 'meta', '120246058389690658', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_952386692927446' AND ad_id='120246058389690658') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='a933caaac21cd461' AND ad_id='120246058389690658');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('99fe28399b99f8ae', 'act_952386692927446', 'ae179d34b851e3e1', 1, 2, 2, 'live', 'This is what a $15 necklace did to my neck', 'Show the green line an old necklace left and say why this one will not.', 'Men and women who have bought a cheap chain. Everyone.', NULL, 'Talking to camera', NULL, '["Has a necklace ever turned your neck green? Mine did this.", "This is what a fifteen-dollar necklace did to me.", "Why does jewelry turn you green? One word."]', '[{"label": "Open · 0 to 3s", "text": "The old chain in hand, against the neck."}, {"label": "Middle", "text": "The copper answer, then the new piece going on, close on the skin."}, {"label": "Close", "text": "A week later, same spot, no line."}]', 'Why it turns green: copper. / 18K gold-filled. Won''t turn your skin green.', 'Keep the old chain anonymous.', 'Name a competitor brand.', NULL, 'You pull a dull old chain out of a drawer or your bag and hold it against your neck.', '"Do you know why it does that?" One word: copper. Then the Ice & Gold piece goes on.', 'A street-interview ad built on "has it ever turned your neck green?" has run four months for Craftd. It is the one memory every buyer has.', '[{"brand": "Craftd", "what": "The exchange: \"Has it ever turned your neck green before?\" \"Yeah.\" \"Do you know why?\" \"Uh, copper?\"", "url": "https://app.tryatria.com/ad/m1073914602481069"}, {"brand": "JAXXON", "what": "\"Never wear a chain like this unless you want your skin to turn green.\"", "url": "https://app.tryatria.com/ad/m1541606723604426"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('68577e7bcc43853f', 'act_952386692927446', 'ae179d34b851e3e1', 0, 0, 3, 'live', 'Same earrings. Gym, shower, brunch.', 'One pair worn through a workout, a shower and brunch, no changes.', 'Denise. Works for a man with a chain too.', 'Gold Link Earrings, Mixed Metal Link Earrings', 'Montage', NULL, '["Same earrings, three places, no taking them off.", "I used to take my jewelry off for the gym. Not anymore.", "Watch these go from the gym to brunch."]', '[{"label": "Open · 0 to 3s", "text": "The gym mirror, the rep."}, {"label": "Middle", "text": "Shower steam, earrings in."}, {"label": "Close", "text": "Brunch table, the water glass as the light."}]', 'Sweat proof. Hypoallergenic. Still on.', 'Identical pair in every cut.', 'Stack other brands into it.', NULL, 'Mid-rep in the gym, the Gold Link Earrings clearly visible, sweat on the skin.', 'Hard cut to the same earrings at the brunch table, same angle. Text: same pair.', '"You get your pump and you got your chain on" is how the men''s chain brands prove it; nobody films it for earrings.', '[{"brand": "Craftd", "what": "The gym as the proof setting.", "url": "https://app.tryatria.com/ad/m1073914602481069"}, {"brand": "JAXXON", "what": "\"The gym, the club, the shower, it stays looking brand new.\"", "url": "https://app.tryatria.com/ad/m1541606723604426"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'ca71b9e327aaa469', 'act_952386692927446', '68577e7bcc43853f', 'meta', '120246058389690658', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_952386692927446' AND ad_id='120246058389690658') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='68577e7bcc43853f' AND ad_id='120246058389690658');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('3ac312580d64ccb7', 'act_952386692927446', 'ae179d34b851e3e1', 0, 0, 4, 'live', 'Nobody tells you this when you buy gold jewelry', 'Why gold-filled and gold PVD last and thin layers do not, with two pieces in hand.', 'The sceptic who has been burned. Our "how to buy gold jewelry" ad is our best explainer.', NULL, 'Talking to camera', NULL, '["Nobody tells you this when you buy gold jewelry.", "There are three kinds of gold jewelry and only two are worth your money.", "Here''s how I check if a chain will last."]', '[{"label": "Open · 0 to 3s", "text": "The two chains, the rub."}, {"label": "Middle", "text": "Close on the clasp and the link finish of the Ice & Gold piece."}, {"label": "Close", "text": "The Ice & Gold piece on you."}]', 'Gold-filled: a thick layer of gold bonded to the metal. / Gold PVD: gold bonded to steel, made for daily wear.', 'Use the words on the product pages: 18K gold-filled, tarnish-resistant, hypoallergenic.', 'Say "gold plated" even about the cheap one. Say "the thin stuff".', NULL, 'Two chains side by side on a dark cloth, your fingers rubbing the cheap one.', '"The difference is how much gold is actually on it." Text on screen puts it in plain words.', 'Our own explainer ad is one of the best things in the account. The category brands run "don''t get ripped off" comparisons for the same reason.', '[{"brand": "Craftd", "what": "The \"don''t get ripped off\" price and quality comparison.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '7906017d102e4868', 'act_952386692927446', '3ac312580d64ccb7', 'meta', '120241168770620658', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_952386692927446' AND ad_id='120241168770620658') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='3ac312580d64ccb7' AND ad_id='120241168770620658');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('16586a2ef027249f', 'act_952386692927446', 'ae179d34b851e3e1', 0, 0, 5, 'live', 'Day 30. Let me show you the clasp first.', 'Commit on camera to 30 days and post the check-in as the ad.', 'Denise and Babs. The "I have been burned" buyer.', NULL, 'Day counter', NULL, '["Thirty days ago I said if this tarnished I''m done with gold jewelry.", "I didn''t take this off for a month. Here''s the honest result.", "Day 30. Let me show you the clasp first."]', '[{"label": "Open · 0 to 3s", "text": "Day 30 note, piece in hand."}, {"label": "Middle", "text": "The month in five cuts."}, {"label": "Close", "text": "The clasp and the back of the pendant in daylight. That is where cheap pieces fail."}]', 'Day 1 / Day 30 / No fade. No green.', 'Show the back of the pendant and the clasp.', 'Fake the date.', NULL, 'The piece held to camera with a hand-written "Day 30" note or the phone date visible.', 'Flash back to day 1 (same shirt if you can), then back to today.', 'JAXXON runs a 30-day test format and a two-month press test on a rival ended "still tarnish-free". A dated test is proof you can picture.', '[{"brand": "JAXXON", "what": "\"If this chain tarnishes in 30 days I''m done with chains forever.\"", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '60aeb9e40bdca801', 'act_952386692927446', '16586a2ef027249f', 'meta', '120246847628540658', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_952386692927446' AND ad_id='120246847628540658') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='16586a2ef027249f' AND ad_id='120246847628540658');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('a3d45abf554d3aed', 'act_952386692927446', 'ae179d34b851e3e1', 0, 0, 6, 'live', 'Every necklace that turned on me', 'Dump the drawer of dead jewelry on the table and say why you stopped buying it.', 'Women 30 to 55 with a drawer like this. Lola.', NULL, 'Talking to camera', NULL, '["This is every necklace that turned on me.", "Twelve years of jewelry that didn''t last. One that did.", "If your jewelry drawer looks like this, keep watching."]', '[{"label": "Open · 0 to 3s", "text": "The tip-out."}, {"label": "Middle", "text": "The single Ice & Gold piece on top."}, {"label": "Close", "text": "The piece on you."}]', 'All of this: a few months each. / This one: a year and counting.', 'Count the money wasted out loud.', 'Show brand logos on the dead pieces.', NULL, 'A drawer or pouch tipped out on the table: dull chains, green-tinged hoops.', 'One Ice & Gold piece placed on top of the pile. The contrast does the work.', '"Unless you like wasting money" is the line the men''s brands open on. Counting the money wasted out loud lands.', '[{"brand": "JAXXON", "what": "The \"never buy a chain like this unless you like wasting money\" opener.", "url": "https://app.tryatria.com/ad/m1541606723604426"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('29bea4365765b175', 'act_952386692927446', '7da893f905e6893a', 1, 3, 7, 'live', 'He opened it, went quiet, and put it on', 'She buys the Cuban for his birthday or Christmas, checks it first, films him opening it.', 'The woman who buys for Babs. She is the buyer; he is the wearer.', '12mm Diamond Clasp Cuban, 10mm Miami Cuban set', 'Reaction', NULL, '["It''s his birthday and he has no say in what he''s getting.", "I checked it before he got home. The weight surprised me.", "He opened it, didn''t say anything, and put it on. Still on."]', '[{"label": "Open · 0 to 3s", "text": "Her hands, the chain, the weight."}, {"label": "Middle", "text": "The handover. Hold on his face."}, {"label": "Close", "text": "Him wearing it at dinner, then at the gym a week later."}]', '12mm Diamond Clasp Cuban. 1-year warranty. Ships free.', 'Let her say the weight and shine felt more expensive than the price.', 'Let him do the talking. The buyer is her.', NULL, 'Her hands opening his box before he gets home, the chain lifted out and weighed in her palm.', '"He has no say in this." Then the handover and his pause.', 'The cleanest gifting script in jewelry is a wife doing exactly this for JAXXON. We have the chain at a lower price.', '[{"brand": "JAXXON", "what": "The whole script: checked it early, engraved clasp, \"went quiet for a second, and just put it on\", three months later no green.", "url": "https://app.tryatria.com/ad/m1362619162625683"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('0f398f3d20947691', 'act_952386692927446', '7da893f905e6893a', 0, 0, 8, 'live', 'Four gifts, one order', 'Four pieces on the table, one for each woman on your list, and the bundle price if it is live.', 'Lola and Denise buying for a list.', 'Water Drop Set, Gold Link Earrings, Spiral Set, Screw-On Gem Bracelet', 'Flat lay', NULL, '["I''m buying jewelry for four women and only one of them is me.", "Mom gets the Water Drop set. Here is why.", "Every woman in my family is getting gold this year."]', '[{"label": "Open · 0 to 3s", "text": "Four boxes, four names."}, {"label": "Middle", "text": "Each piece out of its box, on your hand or ear, one line each."}, {"label": "Close", "text": "The pile wrapped, \"and this one''s mine\"."}]', 'Four women. One order. Free US shipping.', 'Say who each one is for. If Pick Any 4 for $150 is live that day, say it exactly as the site does.', 'Say "treat yourself". Say "and this one''s mine".', NULL, 'Four Ice & Gold boxes lined up, your hand sliding them into frame one by one.', 'Each box gets a name: Mom, Auntie, Tola, me. The fourth is for you.', 'Set and gift-with-purchase offers are running at GLD, Craftd and Olivia & Pearl right now; the list-of-people shape makes a set video feel like a story.', '[{"brand": "Olivia & Pearl", "what": "Gift pitch with the sold-out-last-year urgency and a free bracelet over a spend.", "url": "https://app.tryatria.com/ad/m2154889298715714"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'ca78b169ddbd58a4', 'act_952386692927446', '0f398f3d20947691', 'meta', '120241282267840658', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_952386692927446' AND ad_id='120241282267840658') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='0f398f3d20947691' AND ad_id='120241282267840658');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('28aa96f7377a4592', 'act_952386692927446', '7da893f905e6893a', 0, 0, 9, 'live', 'My mom hasn''t bought herself jewelry in ten years. Watch.', 'The real reaction when a mother or sister opens the box, filmed by the giver.', 'Lola''s daughters, and husbands buying for Lola.', 'Water Drop Set, Gold Link Set, Lariat Heart Set', 'Reaction', NULL, '["My mom hasn''t bought herself jewelry in ten years. Watch.", "I got her the set she kept screenshotting.", "She didn''t say anything for a second. Then she put it on."]', '[{"label": "Open · 0 to 3s", "text": "The box handover."}, {"label": "Middle", "text": "The pause on her face."}, {"label": "Close", "text": "The piece on her, smiling."}]', 'The Water Drop Set. Ships free in the US.', 'Camera on her hands and face, not the giver.', 'Script the reaction.', NULL, 'Hands holding the box out to someone, the recipient not yet in frame.', 'The lid lifts, the pause, then she puts it on without being asked.', '"My niece went bonkers over the earrings" is how real reviews talk. The quiet-then-puts-it-on beat is the payoff everyone waits for.', '[{"brand": "JAXXON", "what": "The giver tells it: \"He opened it, went quiet for a second, and just put it on.\"", "url": "https://app.tryatria.com/ad/m1362619162625683"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'e672551595b6a001', 'act_952386692927446', '28aa96f7377a4592', 'meta', '120241282267840658', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_952386692927446' AND ad_id='120241282267840658') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='28aa96f7377a4592' AND ad_id='120241282267840658');
