INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('b9a7643ce9e30503', 'act_952386692927446', 'fa06522a5183bf87', 0, 0, 24, 'live', 'Four kids. Twins. This necklace is still on.', 'Fela shows what she wears on a school-run day and why it has to survive four kids.', 'Mothers 30 to 45. The core customer''s daughters.', NULL, 'Founder', NULL, '["Four kids. Twins. This necklace is still on.", "Mom jewelry has one rule: it survives the toddler.", "I make jewelry for women who don''t have time to take it off."]', '[{"label": "Open · 0 to 3s", "text": "The grab."}, {"label": "Middle", "text": "The kitchen, the car."}, {"label": "Close", "text": "The piece at the end of the day."}]', 'Fela, founder, mom of 4. Sweat proof. Kid proof, unofficially.', 'Keep kids'' faces out if Fela prefers.', 'Make it a brand monologue.', NULL, 'A toddler''s hand grabbing the necklace, or the car seat buckle with the bracelet in frame.', '"Mom of four, including twins." Then the piece surviving the day.', 'A mother-angle jewelry ad is rising this month for Tini Lux; our founder is a mom of four and already on camera.', '[{"brand": "Tini Lux", "what": "The sensitive-ears pain aimed at mothers.", "url": "https://app.tryatria.com/ad/m1607002081161098"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '770a64dce65fe5e9', 'act_952386692927446', 'b9a7643ce9e30503', 'meta', '120247211799640658', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_952386692927446' AND ad_id='120247211799640658') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='b9a7643ce9e30503' AND ad_id='120247211799640658');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('cd143112739e339e', 'act_952386692927446', 'fa06522a5183bf87', 0, 0, 25, 'live', 'I don''t have to explain this one', 'The Africa pendant as the piece that says it without saying it.', 'The core customer and the wider diaspora. Men and women.', 'Africa Pendant and Chain', 'Talking to camera', NULL, '["I don''t have to explain this one.", "Where I''m from, on a chain.", "My dad saw it and asked for one. So now we match."]', '[{"label": "Open · 0 to 3s", "text": "Pendant on the chest, hand on it."}, {"label": "Middle", "text": "The pendant in hand."}, {"label": "Close", "text": "Two people wearing it."}]', 'Africa Pendant and Chain. Gold-filled. Tarnish free.', 'Say your specific country.', 'Make it a history lesson.', NULL, 'The pendant on your chest, your hand resting on it, a flag or family photo soft behind you.', '"My dad asked where I got it. Then asked for one."', 'A creator at JAXXON tied a medallion to being Italian and it is their best creator ad. Heritage on a chain needs no explaining.', '[{"brand": "JAXXON", "what": "The creator tying the medallion to his own heritage.", "url": "https://app.tryatria.com/ad/m1690346978705251"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('cb4cd2cb3b961fcc', 'act_952386692927446', 'bc2b735e77ae6a12', 0, 0, 26, 'live', 'If you''ve never worn a chain, start here', 'The one chain to start with: the 6mm Cuban, not the biggest, not the most expensive.', 'Babs and younger men. GQ readers.', '6mm Gold Cuban Link Chain', 'Talking to camera', NULL, '["If you''ve never worn a chain, start here.", "Don''t buy the biggest one. Buy the one you''ll wear every day.", "One chain changes a plain t-shirt. This one."]', '[{"label": "Open · 0 to 3s", "text": "Hand, chain, t-shirt."}, {"label": "Middle", "text": "Chain on, t-shirt, then an open collar."}, {"label": "Close", "text": "The 12mm beside it: \"later\"."}]', '6mm Gold Cuban. Tarnish free. Sweat proof.', 'Two outfits in 15 seconds.', 'Use "iced out" language. The men''s line is clean gold.', NULL, 'A man''s hand holding the 6mm Cuban against a plain t-shirt at the collarbone.', '"Don''t buy the biggest." A 12mm held up next to it for contrast.', 'JAXXON''s number two ad right now is "don''t buy the biggest, don''t buy the most expensive, get something clean". Our office Cuban video is the seed.', '[{"brand": "JAXXON", "what": "\"Don''t overthink it. Don''t buy the biggest, don''t buy the most expensive.\"", "url": "https://app.tryatria.com/ad/m1395239659365715"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'd78dc69785709c1d', 'act_952386692927446', 'cb4cd2cb3b961fcc', 'meta', '120244930393670658', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_952386692927446' AND ad_id='120244930393670658') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='cb4cd2cb3b961fcc' AND ad_id='120244930393670658');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('50fc260c71173e42', 'act_952386692927446', 'bc2b735e77ae6a12', 0, 0, 27, 'live', 'Do you like chains on men? Be honest.', 'A woman asks women whether they like a chain on a man, then shows the Ice & Gold Cuban.', 'Men who need permission. Women who buy for them.', '6mm Gold Cuban Link Chain, 10mm Miami Cuban', 'Street interview', NULL, '["Do you like chains on men? Be honest.", "Quick question for the ladies: chain or no chain?", "I asked ten women the same question."]', '[{"label": "Open · 0 to 3s", "text": "The question."}, {"label": "Middle", "text": "The chain in their hands."}, {"label": "Close", "text": "A man trying it on at the end."}]', '6mm Cuban. Won''t turn his neck green.', 'Unscripted answers.', 'Use a made-up statistic like "73% more dates".', NULL, 'You with a mic walking up to a group of women, first question before any logo.', 'You pull the chain out of your bag and hand it over. Their faces when they feel the weight.', 'Craftd runs "do you like chains on men?" to women because the woman buys the man''s chain.', '[{"brand": "Craftd", "what": "The street interview outside a gym, question first, brand later.", "url": "https://app.tryatria.com/ad/m1073914602481069"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('66297a0003f96ee2', 'act_952386692927446', 'bc2b735e77ae6a12', 0, 0, 28, 'live', 'Lion or compass. Depends what he is going through.', 'The Lion coin and the Compass told as a gift choice: lion for the man starting something, compass for the man leaving home.', 'Women gifting men. Men choosing their own.', 'Gold Lion Coin Pendant, Compass Pendant with Chain', 'Talking to camera', NULL, '["Lion or compass. Depends what he is going through.", "The pendant you give says something. Choose it on purpose.", "My brother got the compass when he moved to Houston."]', '[{"label": "Open · 0 to 3s", "text": "The two pendants."}, {"label": "Middle", "text": "One on a chain on a man."}, {"label": "Close", "text": "The box."}]', 'Gold Lion Coin Pendant. Compass Pendant.', 'Tie the pendant to a moment in a man''s life.', 'Film the compass as a product spin again.', NULL, 'Two pendants on the table, your finger moving from one to the other.', '"I gave the lion to my brother when he..." The personal story.', 'Our Lion coin creator video sold; our Compass try-on sold nothing. The pendant needs the meaning.', '[{"brand": "JAXXON", "what": "Graduation-gift pendants: \"guidance for his next chapter\".", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'ff3c3689f4449bcf', 'act_952386692927446', '66297a0003f96ee2', 'meta', '120246847917810658', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_952386692927446' AND ad_id='120246847917810658') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='66297a0003f96ee2' AND ad_id='120246847917810658');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('94812694a65a1ea8', 'act_952386692927446', 'bc2b735e77ae6a12', 0, 0, 29, 'live', 'Cape off, chain on', 'At the barber, the cape comes off and the chain is the first thing back on. The barber reacts.', 'Babs and younger men. Atlanta.', '10mm Miami Cuban set, 6mm Gold Cuban', 'Skit', NULL, '["Cape off, chain on.", "The barber asked. So here.", "Fresh cut, clean chain, Saturday."]', '[{"label": "Open · 0 to 3s", "text": "Cape off."}, {"label": "Middle", "text": "The chain in the mirror."}, {"label": "Close", "text": "The barber holding it."}]', 'Men''s Cuban chains.', 'Under 20 seconds, shop sound on.', 'Add a voiceover.', NULL, 'The cape being pulled off, the chain catching the light as he sits up.', 'The barber asks where it is from and feels the weight.', '"Every detail matters. How you train, how you show up, what you wear." The barbershop is where men talk about looking good.', '[{"brand": "JAXXON", "what": "\"Every detail matters\" in 11 seconds.", "url": "https://app.tryatria.com/ad/m1054013177246892"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('70a0850e3b2a7700', 'act_952386692927446', 'bc2b735e77ae6a12', 0, 0, 30, 'live', 'Twitch, what''s the only chain you wear?', 'Two men talking about a chain is the only format where a man admits he cares about jewelry.', 'Babs. Men 30 to 55.', '10mm Miami Cuban, 6mm Gold Cuban, 3mm Gold Rope', 'Podcast clip', NULL, '["What''s the only chain you wear when you step out?", "Which one never comes off?", "Okay, chain talk. Go."]', '[{"label": "Open · 0 to 3s", "text": "The question across the table."}, {"label": "Middle", "text": "Both chains out, the weight."}, {"label": "Close", "text": "One line each on why."}]', '10mm Miami Cuban. 6mm Cuban. Sweat proof.', 'Real friends, real chains.', 'Script it.', NULL, 'Two men at a table or in a car, mics or phones, one asks the other what chain he wears.', '"Never comes off my neck. Sweat proof." The other one pulls his out.', 'JAXXON has run a podcast clip built on this question for over four months.', '[{"brand": "JAXXON", "what": "\"Twitch, what''s the only chain you wear when you step out?\"", "url": "https://app.tryatria.com/ad/m1513411913702715"}]');
