INSERT OR IGNORE INTO p_amb_brand (act_id, slug, live, display_name, submit_platform, submit_label) VALUES ('act_952386692927446', 'ice-and-gold', 0, 'Ice & Gold', 'TRYBE', 'Film this on TRYBE');
UPDATE p_amb_brand SET display_name='Ice & Gold', intro='Ice & Gold is everyday gold jewelry from Atlanta, started by Fela, a mom of four whose mother sold gold in Nigeria. It is 18K gold-filled and gold PVD, so it does not tarnish, does not turn your skin green, and you never have to take it off. The videos that sell it are people wearing it in real light, not product spins. Pick an idea, do the first second the way it says, and submit it on TRYBE.', about='Sets for the party and the wedding (Water Drop Set, Gold Link Set, Spiral Set, Lariat Heart Set, Studded Herringbone & Hoop Set), earrings and chains you never take off (Gold Link Earrings, Mixed Metal Link Earrings, Twisted Herringbone, Screw-On Gem Bracelet), letter pendants and the Africa pendant, and a men''s line of clean Cuban, rope and Figaro chains, the Lion coin and the Compass. Free US shipping on every order, 1-year warranty, free gift over $250. Prices are on the site; read them off it the day you post.', audience='Denise, 35, makes content, buys earrings or a necklace she will wear every day. Lola, 50, parties, weddings and church, buys the set. Babs, 41, wants to look good and buys the men''s chain, or his wife buys it for him. Most of our customers are Nigerian-American and Black women in and around Atlanta, and six in ten come back, so talk to the woman who already owns one piece too.', accent='#C9A84C', logo_url='https://iceandgold.com/cdn/shop/files/WhatsApp_Image_2026-07-21_at_7.56.24_PM_1.png?v=1785321904&width=360', submit_label='Film this on TRYBE', submit_platform='TRYBE', avoid_json='[{"title": "The piece on marble with a voiceover and no person", "why": "Both of our agency statics lost. Every creator try-on beat them. If nobody is wearing it, we cannot use it."}, {"title": "A plain try-on of the Compass pendant", "why": "It ran and sold nothing. The pendant sells on what it means to the man you give it to, not on a spin."}, {"title": "A haul of six pieces with no hero", "why": "Our best creator video was one pair of earrings on one ear. Give people one thing to buy."}, {"title": "\"Real gold\" tests: vinegar, magnet, acid", "why": "Ice & Gold is gold-filled and gold PVD, not solid gold. Prove tarnish and sweat, never purity."}, {"title": "Luxury-ad words: elevate, timeless elegance, main character energy, treat yourself", "why": "It reads as copy. The best jewelry ads right now talk like a person: \"Uh, excuse me, this is our best seller.\""}, {"title": "Pulling the herringbone over your head on camera", "why": "Herringbone chains kink. Clasp it, lay it flat, show it on."}]', rules_json='["Say \"18K gold-filled\" or \"gold PVD\". Never \"gold plated\", never \"real gold\", never \"solid gold\".", "Say \"tarnish free\", \"sweat proof\", \"hypoallergenic\", \"won''t turn your skin green\". Say \"water resistant\", not \"waterproof\", until we confirm.", "Say \"designed in Atlanta\". Not \"made in Atlanta\".", "Free US shipping on every order. 1-year warranty. Free gift when you spend over $250.", "Money-back window: say nothing until we confirm the number of days.", "Name the piece and read its price off the site the day you post. Prices change with sales.", "Code Gold15 is 15% off and anyone can say it. Code Adeola is hers; only she uses it.", "Film in daylight by a window or outside. Gold on skin, never gold on a table.", "Only film people who agreed to be in your video. Kids: faces out unless the parent says yes."]', season_json='{"title": "Black Friday and Christmas build", "until": "Nov 20", "line": "Film the proof videos and the gift videos now so they are live by Nov 10. Black Friday week and the December weddings and parties are the biggest weeks of the year for us. Valentine''s follows in January.", "next": "Black Friday and Cyber Monday from Nov 27, Christmas last ship date in December, Valentine''s from Jan 15", "highlight": ["10-06", "12-20"], "show_chart": false, "color": "#C9A84C"}', guide_json='[{"title": "Be wearing it before you say a word", "text": "Face in frame, piece catching the light, mid-sentence. The best jewelry ad in the category opens on the founder already holding the chain: \"Uh, excuse me.\""}, {"title": "Water, sweat or a pillow in the first second", "text": "The shower head, the gym mirror, the bed. Everyone has had a necklace turn on them, so showing it survive is the hook. No claim beats a picture of water on gold."}, {"title": "Say the embarrassing thing out loud", "text": "\"Has a necklace ever turned your neck green?\" A street-interview ad built on that one question has run four months for another brand. Then show the fix."}, {"title": "Give them a day counter", "text": "Day 1, Day 4, Day 7 on screen. A number that climbs is the simplest reason to keep watching, and it is the proof."}, {"title": "Change the picture every 3 seconds", "text": "Bathroom, car, church door, party. Same earrings in every cut. If you have been talking for 8 seconds without moving, cut."}, {"title": "Name the piece. Then the price, from the site", "text": "\"This is the Water Drop Set.\" Say it, show it, put it on screen. A piece with no name cannot be bought."}, {"title": "Let the other person react", "text": "She opens the box and goes quiet, then puts it on. He feels the weight of the chain. The pause is the ad. Do not script it."}, {"title": "End on it being worn, and who it is for", "text": "\"If you have the earrings, this is the necklace.\" Then the code. No \"link in bio\", no wrap-up speech."}]', updated_at=datetime('now') WHERE act_id='act_952386692927446';
